"use client";

import { useState, useEffect, useRef, useCallback } from "react";
import Image from "next/image";
import { motion, AnimatePresence } from "framer-motion";
import { 
  User, CheckCircle, XCircle, Clock, 
  Settings, Volume2, VolumeX, Zap, Camera, ScanFace,
  QrCode, Calendar, Plus, ChevronDown, MapPin, 
  Target, Users, Info, Loader2, RefreshCw, X,
  ShieldCheck, AlertTriangle, ArrowLeft, Maximize2,
  Activity, BarChart3, LayoutGrid, History
} from "lucide-react";
import TourGuide from "@/components/TourGuide";
import { scanAbsensi, createAcara, getDaftarAcara, getLogsByAcara } from "@/lib/actions"; 
import { Html5Qrcode } from "html5-qrcode";

const absensiTourSteps = [
    { target: '.tour-acara-header', content: 'Kelola sesi absensi aktif Anda di sini.', disableBeacon: true },
    { target: '.tour-scanner-btn', content: 'Klik di sini untuk meluncurkan mode kamera scanner yang profesional.', },
    { target: '.tour-activity-stream', content: 'Pantau log kehadiran real-time yang tersimpan aman di database.', placement: 'left' as const },
];

export default function ScanClient() {
  const [isClient, setIsClient] = useState(false);
  const [viewMode, setViewMode] = useState<'manage' | 'scanning'>('manage');
  
  // DATA STATES
  const [logs, setLogs] = useState<any[]>([]);
  const [daftarAcara, setDaftarAcara] = useState<any[]>([]);
  const [selectedAcaraId, setSelectedAcaraId] = useState<number | null>(null);
  const [scanResult, setScanResult] = useState<any>(null);
  
  // UI STATES
  const [isLoadingLogs, setIsLoadingLogs] = useState(false);
  const [isModalOpen, setIsModalOpen] = useState(false);
  const [soundEnabled, setSoundEnabled] = useState(true);
  const [isSubmittingAcara, setIsSubmittingAcara] = useState(false);
  const [newAcara, setNewAcara] = useState({ nama: "", tanggal: new Date().toISOString().split('T')[0], lokasi: "Sekolah" });

  const scannerRef = useRef<Html5Qrcode | null>(null);

  // --- 1. DATA FETCHING ---
  const loadData = useCallback(async (autoSelectLatest = false) => {
    setIsLoadingLogs(true);
    try {
        const list = await getDaftarAcara();
        setDaftarAcara(list);
        
        if (list.length > 0) {
            let targetId = selectedAcaraId;
            if (autoSelectLatest || !selectedAcaraId) {
                targetId = list[0].id;
                setSelectedAcaraId(targetId);
            }
            if (targetId) {
                const dbLogs = await getLogsByAcara(targetId);
                setLogs(dbLogs.map(item => ({
                    name: item.pengurus.nama,
                    role: item.pengurus.jabatan,
                    image: item.pengurus.fotoUrl,
                    time: new Date(item.tanggal).toLocaleTimeString('id-ID', { hour: '2-digit', minute: '2-digit' }),
                    status: item.status,
                    scanId: item.id
                })));
            }
        }
    } catch (err) {
        console.error(err);
    } finally {
        setIsLoadingLogs(false);
    }
  }, [selectedAcaraId]);

  useEffect(() => {
    setIsClient(true);
    loadData();
  }, []);

  // --- 2. SCANNER ENGINE ---
  const startScanner = async () => {
    if (!isClient || !selectedAcaraId) return;
    
    try {
        setTimeout(async () => {
            const element = document.getElementById("reader");
            if (!element) return;

            if (scannerRef.current) {
                try { await scannerRef.current.stop(); } catch (e) {}
                scannerRef.current = null;
            }

            const html5QrCode = new Html5Qrcode("reader");
            scannerRef.current = html5QrCode;
            
            await html5QrCode.start(
                { facingMode: "environment" }, 
                { 
                    fps: 20, 
                    qrbox: (w, h) => {
                        const s = Math.min(w, h) * 0.8;
                        return { width: s, height: s };
                    },
                    aspectRatio: 1.0 
                },
                (text) => handleScan(text),
                () => {}
            );
        }, 300);
    } catch (err) {
        console.warn("Scanner init failed", err);
    }
  };

  const stopScanner = async () => {
    if (scannerRef.current && scannerRef.current.isScanning) {
        await scannerRef.current.stop();
        scannerRef.current = null;
    }
  };

  useEffect(() => {
    if (viewMode === 'scanning') {
        startScanner();
    } else {
        stopScanner();
    }
    return () => { stopScanner(); };
  }, [viewMode, selectedAcaraId]);

  // --- 3. HANDLERS ---
  const handleScan = async (nis: string) => {
    if (!nis || scanResult || !selectedAcaraId) return;
    
    if (soundEnabled) {
        new Audio('https://assets.mixkit.co/active_storage/sfx/2869/2869-preview.mp3').play().catch(() => {});
    }

    try {
        const result = await scanAbsensi(nis, selectedAcaraId);
        if (result.success && result.data) {
            const timestamp = new Date().toLocaleTimeString('id-ID', { hour: '2-digit', minute: '2-digit' });
            const newEntry = { ...result.data, time: timestamp, scanId: Date.now() };
            setScanResult({ type: 'success', data: newEntry, message: result.message });
            setLogs(prev => [newEntry, ...prev]);
        } else {
            setScanResult({ type: 'error', message: result.message });
        }
    } catch (err) {
        setScanResult({ type: 'error', message: "System Error" });
    }
    setTimeout(() => { setScanResult(null); }, 2000);
  };

  const handleCreateAcara = async (e: React.FormEvent) => {
    e.preventDefault();
    setIsSubmittingAcara(true);
    const formData = new FormData();
    formData.append("nama", newAcara.nama);
    formData.append("tanggal", newAcara.tanggal);
    formData.append("lokasi", newAcara.lokasi);

    const res = await createAcara(formData);
    if (res.success) {
        setIsModalOpen(false);
        setNewAcara({ nama: "", tanggal: new Date().toISOString().split('T')[0], lokasi: "Sekolah" });
        await loadData(true); 
    }
    setIsSubmittingAcara(false);
  };

  const selectedAcara = daftarAcara.find(a => a.id === selectedAcaraId);

  // --- RENDERER: MANAGEMENT DASHBOARD ---
  const renderManagement = () => (
    <div className="flex-1 flex flex-col lg:flex-row gap-6 overflow-hidden h-full">
        
        {/* LEFT SIDEBAR: EVENTS LIST */}
        <div className="w-full lg:w-80 shrink-0 flex flex-col gap-4 bg-white dark:bg-[#0f172a] border border-slate-200 dark:border-white/5 rounded-2xl p-5 shadow-sm overflow-hidden h-full">
            <div className="flex justify-between items-center px-1">
                <h3 className="text-sm font-bold text-slate-900 dark:text-white flex items-center gap-2">
                    <Users className="text-blue-600" size={18} /> Sesi Acara
                </h3>
                <button onClick={() => setIsModalOpen(true)} className="p-1.5 bg-blue-600 text-white rounded-lg hover:scale-105 active:scale-95 transition-all">
                    <Plus size={14} strokeWidth={3} />
                </button>
            </div>
            
            <div className="flex-1 overflow-y-auto space-y-2 pr-1 custom-scrollbar">
                {daftarAcara.map((acara) => (
                    <div 
                        key={acara.id} 
                        onClick={() => setSelectedAcaraId(acara.id)}
                        className={`p-3 rounded-xl cursor-pointer transition-all border ${selectedAcaraId === acara.id 
                            ? 'bg-blue-600 text-white border-blue-400 shadow-md scale-[1.01]' 
                            : 'bg-transparent text-slate-600 dark:text-slate-400 border-transparent hover:bg-slate-50 dark:hover:bg-white/5'}`}
                    >
                        <h4 className="text-xs font-bold truncate uppercase tracking-tight">{acara.nama}</h4>
                        <p className={`text-[10px] font-medium mt-1 flex items-center gap-1 ${selectedAcaraId === acara.id ? 'text-blue-100' : 'text-slate-400'}`}>
                            <Calendar size={10} /> {new Date(acara.tanggal).toLocaleDateString('id-ID')}
                        </p>
                    </div>
                ))}
            </div>
        </div>

        {/* RIGHT CONTENT: STATS & LOGS */}
        <div className="flex-1 flex flex-col gap-6 overflow-hidden">
            
            {/* TOP ACTIONS & STATS */}
            <div className="grid grid-cols-1 md:grid-cols-3 gap-6">
                <div className="bg-white dark:bg-[#0f172a] p-6 rounded-2xl border border-slate-200 dark:border-white/5 shadow-sm flex flex-col justify-center">
                    <p className="text-slate-500 dark:text-slate-400 text-[10px] font-bold uppercase tracking-widest mb-1">Total Hadir</p>
                    <div className="flex items-baseline gap-2">
                        <span className="text-4xl font-black text-slate-900 dark:text-white tracking-tighter">{logs.filter(l => l.status === 'HADIR').length}</span>
                        <span className="text-sm font-medium text-slate-400">Pengurus</span>
                    </div>
                </div>
                
                {/* LAUNCH SCANNER CARD */}
                <div 
                    onClick={() => setViewMode('scanning')}
                    className="md:col-span-2 bg-gradient-to-br from-blue-600 to-blue-700 p-6 rounded-2xl text-white shadow-xl shadow-blue-600/20 flex items-center justify-between cursor-pointer hover:brightness-110 transition-all group tour-scanner-btn"
                >
                    <div className="flex items-center gap-5">
                        <div className="w-14 h-14 bg-white/10 rounded-xl flex items-center justify-center backdrop-blur-md">
                            <Maximize2 size={24} />
                        </div>
                        <div>
                            <h4 className="text-xl font-bold tracking-tight leading-none uppercase">Launch Smart Scanner</h4>
                            <p className="text-sm font-medium opacity-70 mt-1">Mulai Sesi Absensi Aktif Secara Real-time</p>
                        </div>
                    </div>
                    <div className="p-2 bg-white/10 rounded-lg group-hover:translate-x-1 transition-transform">
                        <ChevronDown size={20} className="-rotate-90" />
                    </div>
                </div>
            </div>

            {/* LIVE ACTIVITY LOG */}
            <div className="flex-1 bg-white dark:bg-[#0f172a] rounded-2xl border border-slate-200 dark:border-white/5 shadow-sm flex flex-col overflow-hidden tour-activity-stream">
                <div className="p-5 border-b border-slate-100 dark:border-white/5 flex items-center justify-between bg-slate-50/50 dark:bg-transparent">
                    <h3 className="text-sm font-bold text-slate-900 dark:text-white flex items-center gap-3">
                        <Activity size={18} className="text-blue-600" /> Activity Stream
                        {isLoadingLogs && <Loader2 size={14} className="animate-spin text-blue-500" />}
                    </h3>
                </div>
                <div className="flex-1 overflow-y-auto p-4 space-y-3 custom-scrollbar">
                    <AnimatePresence mode="popLayout">
                        {logs.length === 0 ? (
                            <div className="h-full flex flex-col items-center justify-center opacity-20">
                                <History size={48} strokeWidth={1.5} className="mb-3" />
                                <p className="text-[10px] font-bold uppercase tracking-widest">Belum ada aktivitas</p>
                            </div>
                        ) : (
                            logs.map((log) => (
                                <motion.div 
                                    key={log.scanId} layout initial={{ opacity: 0, y: 10 }} animate={{ opacity: 1, y: 0 }}
                                    className="flex items-center gap-4 p-3 rounded-xl bg-white dark:bg-white/5 border border-slate-100 dark:border-white/5 shadow-sm group"
                                >
                                    <div className="relative w-11 h-11 rounded-lg overflow-hidden shrink-0 shadow-sm border border-slate-100 dark:border-white/10">
                                        <Image src={log.image || "https://source.unsplash.com/random/100x100/?portrait"} alt={log.name} fill className="object-cover" />
                                    </div>
                                    <div className="flex-1 min-w-0">
                                        <h4 className="text-sm font-bold text-slate-900 dark:text-white truncate">{log.name}</h4>
                                        <p className="text-[10px] font-medium text-slate-400 uppercase tracking-widest">{log.role}</p>
                                    </div>
                                    <div className="text-right">
                                        <p className="text-[10px] font-bold text-blue-600">{log.time}</p>
                                        <span className={`text-[8px] font-bold px-2 py-0.5 rounded-md uppercase ${log.status === 'DUPLICATE' ? 'bg-amber-100 text-amber-600' : 'bg-emerald-100 text-emerald-600'}`}>
                                            {log.status === 'DUPLICATE' ? 'Double' : 'Hadir'}
                                        </span>
                                    </div>
                                </motion.div>
                            ))
                        )}
                    </AnimatePresence>
                </div>
            </div>
        </div>
    </div>
  );

  // --- RENDERER: SCANNER MODE ---
  const renderScanner = () => (
    <motion.div 
        initial={{ opacity: 0 }} animate={{ opacity: 1 }} exit={{ opacity: 0 }}
        className="fixed inset-0 z-[1000] bg-slate-950 flex flex-col lg:flex-row items-center justify-center p-6 gap-8"
    >
        {/* BACK BUTTON */}
        <button 
            onClick={() => setViewMode('manage')}
            className="absolute top-8 left-8 p-4 bg-white/5 hover:bg-white/10 text-white rounded-xl backdrop-blur-xl border border-white/10 flex items-center gap-3 font-bold text-xs transition-all z-[1100]"
        >
            <ArrowLeft size={16} /> Close Scanner
        </button>

        {/* SCANNER CORE */}
        <div className="w-full max-w-[480px] aspect-square relative rounded-2xl overflow-hidden border-4 border-white/10 shadow-[0_0_50px_rgba(59,130,246,0.2)]">
            <div id="reader" className="absolute inset-0 z-0 [&>video]:object-cover [&>video]:h-full [&>video]:w-full"></div>
            
            {/* UI SCANNER OVERLAY */}
            <div className="absolute inset-0 z-20 flex flex-col items-center justify-center p-10 pointer-events-none">
                <div className="relative w-full h-full border-2 border-white/10 rounded-xl">
                    <div className="absolute -top-1 -left-1 w-12 h-12 border-t-4 border-l-4 border-blue-500 rounded-tl-lg shadow-[0_0_15px_rgba(59,130,246,0.5)]"></div>
                    <div className="absolute -top-1 -right-1 w-12 h-12 border-t-4 border-r-4 border-blue-500 rounded-tr-lg shadow-[0_0_15px_rgba(59,130,246,0.5)]"></div>
                    <div className="absolute -bottom-1 -left-1 w-12 h-12 border-b-4 border-l-4 border-blue-500 rounded-bl-lg shadow-[0_0_15px_rgba(59,130,246,0.5)]"></div>
                    <div className="absolute -bottom-1 -right-1 w-12 h-12 border-b-4 border-r-4 border-blue-500 rounded-br-lg shadow-[0_0_15px_rgba(59,130,246,0.5)]"></div>
                    
                    {!scanResult && (
                        <motion.div 
                            animate={{ top: ["5%", "95%", "5%"] }} 
                            transition={{ duration: 2.5, repeat: Infinity, ease: "linear" }}
                            className="absolute left-[10%] w-[80%] h-0.5 bg-blue-400 shadow-[0_0_20px_rgba(59,130,246,0.8)]"
                        />
                    )}

                    {/* SCAN RESULT PANEL */}
                    <AnimatePresence>
                        {scanResult && (
                            <motion.div 
                                initial={{ opacity: 0, scale: 0.95 }} animate={{ opacity: 1, scale: 1 }} exit={{ opacity: 0 }}
                                className={`absolute inset-0 flex flex-col items-center justify-center text-center p-8 backdrop-blur-2xl rounded-xl z-50 pointer-events-auto ${scanResult.type === 'success' ? (scanResult.data.status === 'DUPLICATE' ? 'bg-amber-950/90' : 'bg-emerald-950/90') : 'bg-rose-950/90'}`}
                            >
                                {scanResult.type === 'success' ? (
                                    <>
                                        <div className="w-32 h-32 rounded-full p-1.5 mb-6 bg-white/10 ring-2 ring-white/20 shadow-2xl">
                                            <div className="relative w-full h-full rounded-full overflow-hidden border-2 border-white">
                                                <Image src={scanResult.data.image || "https://source.unsplash.com/random/100x100/?portrait"} alt="User" fill className="object-cover" />
                                            </div>
                                        </div>
                                        <h2 className="text-2xl font-bold text-white mb-1 tracking-tight uppercase">{scanResult.data.name}</h2>
                                        <p className="text-[10px] font-medium text-white/50 uppercase tracking-[0.3em] mb-8">{scanResult.data.role}</p>
                                        <div className={`px-8 py-3.5 rounded-xl font-bold text-xs shadow-2xl bg-white ${scanResult.data.status === 'DUPLICATE' ? 'text-amber-700' : 'text-emerald-700'}`}>
                                            {scanResult.message}
                                        </div>
                                    </>
                                ) : (
                                    <>
                                        <XCircle size={80} className="text-rose-500 mb-6" />
                                        <h2 className="text-xl font-bold text-white mb-2 uppercase">Gagal Scan</h2>
                                        <p className="text-[10px] text-rose-200 font-bold uppercase tracking-widest bg-rose-900/50 px-6 py-3 rounded-xl border border-rose-500/30">{scanResult.message}</p>
                                    </>
                                )}
                            </motion.div>
                        )}
                    </AnimatePresence>
                </div>
            </div>
        </div>

        {/* SIDE ACTIVITY Peek */}
        <div className="w-full lg:w-72 h-[350px] lg:h-[480px] bg-white/5 backdrop-blur-2xl border border-white/10 rounded-2xl p-5 flex flex-col overflow-hidden">
            <h3 className="text-[10px] font-bold text-blue-400 uppercase tracking-widest mb-5 flex items-center gap-2">
                <Activity size={14} /> Terkini
            </h3>
            <div className="flex-1 overflow-y-auto space-y-3 custom-scrollbar pr-1">
                {logs.slice(0, 5).map((log) => (
                    <div key={log.scanId} className="flex items-center gap-3 p-2.5 rounded-xl bg-white/5 border border-white/5">
                        <div className="relative w-9 h-9 rounded-lg overflow-hidden shrink-0">
                            <Image src={log.image || "https://source.unsplash.com/random/100x100/?portrait"} alt="" fill className="object-cover" />
                        </div>
                        <div className="min-w-0 flex-1">
                            <h4 className="text-[10px] font-bold text-white truncate">{log.name}</h4>
                            <p className="text-[8px] font-medium text-slate-500 uppercase">{log.role}</p>
                        </div>
                    </div>
                ))}
            </div>
        </div>
    </motion.div>
  );

  return (
    <div className="h-[calc(100vh-140px)] flex flex-col gap-6 font-sans">
      
      {/* HEADER SECTION (Identical to ID Card Studio) */}
      <div className="flex flex-col md:flex-row justify-between items-end gap-6 mb-2 shrink-0 px-4 md:px-0">
          <div>
             <div className="flex items-center gap-4">
                <h1 className="text-3xl font-bold text-slate-900 dark:text-white tracking-tight flex items-center gap-3">
                   Smart Attendance <span className="text-2xl p-2 bg-blue-100 dark:bg-blue-900/30 rounded-full">⚡</span>
                </h1>
                {isClient && <TourGuide steps={absensiTourSteps} />}
             </div>
             <p className="text-slate-500 dark:text-slate-400 text-sm font-medium mt-1">Kelola kehadiran organisasi secara efisien dan real-time.</p>
          </div>
          <div className="flex items-center gap-3">
             <button onClick={() => setSoundEnabled(!soundEnabled)} className="p-3 bg-white dark:bg-slate-900 border border-slate-200 dark:border-white/10 rounded-xl text-slate-500 hover:text-blue-600 shadow-sm transition-all">
                {soundEnabled ? <Volume2 size={18}/> : <VolumeX size={18}/>}
             </button>
          </div>
      </div>

      {/* MAIN VIEW AREA */}
      <AnimatePresence mode="wait">
        {viewMode === 'manage' ? (
            <motion.div key="manage" initial={{ opacity: 0 }} animate={{ opacity: 1 }} exit={{ opacity: 0 }} className="flex-1 overflow-hidden">
                {renderManagement()}
            </motion.div>
        ) : (
            <motion.div key="scanner" initial={{ opacity: 0 }} animate={{ opacity: 1 }} exit={{ opacity: 0 }} className="absolute inset-0 z-[1000]">
                {renderScanner()}
            </motion.div>
        ) }
      </AnimatePresence>

      {/* MODAL: NEW EVENT */}
      <AnimatePresence>
        {isModalOpen && (
            <div className="fixed inset-0 z-[2000] flex items-center justify-center p-6 backdrop-blur-md">
                <motion.div initial={{ opacity: 0 }} animate={{ opacity: 1 }} exit={{ opacity: 0 }} onClick={() => setIsModalOpen(false)} className="absolute inset-0 bg-slate-900/70" />
                <motion.div 
                    initial={{ opacity: 0, scale: 0.95 }} animate={{ opacity: 1, scale: 1 }} exit={{ opacity: 0, scale: 0.95 }}
                    className="relative w-full max-w-lg bg-white dark:bg-slate-900 rounded-2xl shadow-2xl border border-white/10 overflow-hidden"
                >
                    <div className="p-10">
                        <div className="flex justify-between items-center mb-8">
                            <h2 className="text-xl font-bold text-slate-900 dark:text-white tracking-tight uppercase flex items-center gap-3">
                                <Plus className="text-blue-600" /> Tambah Sesi Acara
                            </h2>
                            <button onClick={() => setIsModalOpen(false)} className="p-2 bg-slate-100 dark:bg-white/5 rounded-lg hover:bg-rose-500 hover:text-white transition-all"><X size={20}/></button>
                        </div>
                        
                        <form onSubmit={handleCreateAcara} className="space-y-6">
                            <div className="space-y-2">
                                <label className="text-[9px] font-bold text-slate-400 uppercase tracking-widest ml-1">Nama Kegiatan</label>
                                <input required value={newAcara.nama} onChange={e => setNewAcara({...newAcara, nama: e.target.value})} type="text" placeholder="e.g. Rapat Koordinasi" className="w-full px-6 py-4 bg-slate-50 dark:bg-slate-800 rounded-xl outline-none text-xs font-medium dark:text-white border border-slate-100 dark:border-white/5 focus:border-blue-500 transition-all shadow-inner" />
                            </div>
                            <div className="grid grid-cols-2 gap-6">
                                <div className="space-y-2">
                                    <label className="text-[9px] font-bold text-slate-400 uppercase tracking-widest ml-1">Timeline</label>
                                    <input required value={newAcara.tanggal} onChange={e => setNewAcara({...newAcara, tanggal: e.target.value})} type="date" className="w-full px-6 py-4 bg-slate-50 dark:bg-slate-800 rounded-xl outline-none text-xs font-medium dark:text-white border border-slate-100 dark:border-white/5 focus:border-blue-500 transition-all shadow-inner" />
                                </div>
                                <div className="space-y-2">
                                    <label className="text-[9px] font-bold text-slate-400 uppercase tracking-widest ml-1">Coordinates</label>
                                    <input required value={newAcara.lokasi} onChange={e => setNewAcara({...newAcara, lokasi: e.target.value})} type="text" placeholder="Location" className="w-full px-6 py-4 bg-slate-50 dark:bg-slate-800 rounded-xl outline-none text-xs font-medium dark:text-white border border-slate-100 dark:border-white/5 focus:border-blue-500 transition-all shadow-inner" />
                                </div>
                            </div>
                            <button disabled={isSubmittingAcara} type="submit" className="w-full py-5 bg-blue-600 text-white rounded-xl font-bold text-xs uppercase tracking-[0.2em] shadow-lg hover:brightness-110 active:scale-95 transition-all">
                                {isSubmittingAcara ? "Deploying..." : "Create Event Session"}
                            </button>
                        </form>
                    </div>
                </motion.div>
            </div>
        )}
      </AnimatePresence>

      <style jsx global>{`
        .custom-scrollbar::-webkit-scrollbar { width: 4px; }
        .custom-scrollbar::-webkit-scrollbar-thumb { background: #3b82f6; border-radius: 10px; }
        .dark .custom-scrollbar::-webkit-scrollbar-thumb { background: #1e293b; }
      `}</style>

    </div>
  );
}